import {loadArt} from './woods-art.mjs?v=starter-rig-2';
import {drawFighter} from './fighter-rig.mjs?v=starter-rig-2';
import {keyBackground} from './sprite-texture.mjs';
export async function assets(){const a=await loadArt();const im=new Image();im.src='assets/crownlands/class-parts.webp';await im.decode();const c=document.createElement('canvas');c.width=im.width;c.height=im.height;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(im,0,0);const p=x.getImageData(0,0,c.width,c.height);keyBackground(p.data,c.width,c.height,4,3);for(let yy=Math.floor(c.height*2/3);yy<c.height;yy++)for(let xx=c.width/2;xx<c.width;xx++){const n=(yy*c.width+xx)*4;if(Math.min(p.data[n],p.data[n+1],p.data[n+2])>235&&Math.max(p.data[n],p.data[n+1],p.data[n+2])-Math.min(p.data[n],p.data[n+1],p.data[n+2])<18)p.data[n+3]=0;}x.putImageData(p,0,0);// Even thirds put a row line at y=724, which sliced 39-51px off the top of every weapon in row 2.
const BANDS=[0,350,670,1086];
a.classes=[];const w=c.width/4;for(let i=0;i<12;i++){const row=Math.floor(i/4),sy=BANDS[row],h=BANDS[row+1]-sy;let l=w,t=h,r=0,b=0;for(let yy=0;yy<h;yy++)for(let xx=0;xx<w;xx++)if(p.data[((sy+yy)*c.width+i%4*w+xx)*4+3]>100){l=Math.min(l,xx);r=Math.max(r,xx);t=Math.min(t,yy);b=Math.max(b,yy);}const out=document.createElement('canvas');out.width=Math.max(1,r-l+1);out.height=Math.max(1,b-t+1);out.getContext('2d').drawImage(c,i%4*w+l,sy+t,out.width,out.height,0,0,out.width,out.height);a.classes.push(out);}return a;}
export function hero(ctx,art,kind,x,y,gear,opts={}){const {scale=1,face=1}=opts;drawFighter(ctx,art,kind,x,y,gear,opts);
 if(gear.magic>0){ctx.save();ctx.strokeStyle=kind==='mage'?'#bb8aff':'#ffe6a0';ctx.lineWidth=2;ctx.globalAlpha=.6;ctx.beginPath();ctx.arc(x+face*45*scale,y-80*scale,7+gear.magic*2,0,Math.PI*2);ctx.stroke();ctx.restore();}}
export function gearImage(art,kind,slot,tier){if(slot==='boots')return kind==='mage'?art.classes[3]:kind==='ranger'?art.classes[7]:art.parts[3];if(slot==='defense')return kind==='mage'?art.classes[1]:kind==='ranger'?art.classes[5]:art.parts[tier>2?8:tier?7:1];if(slot==='magic'){const c=document.createElement('canvas');c.width=100;c.height=120;const x=c.getContext('2d');x.fillStyle=['#b9daef','#a9f7c0','#f4b071','#c3a2ff','#ffe397'][tier];x.font='70px serif';x.textAlign='center';x.fillText('✦',50,83);return c;}if(kind==='mage')return art.classes[tier>1?9:8];if(kind==='ranger')return art.classes[tier>1?11:10];return art.parts[tier>2?6:tier?5:4];}
